import 'package:flutter/material.dart';
import '../core/jalali.dart';
import '../core/persian.dart';
import '../domain/task.dart';
class TaskForm extends StatefulWidget {final Task? initial;const TaskForm({this.initial,Key? key}):super(key:key);@override State<TaskForm> createState()=>_TaskFormState();}
class _TaskFormState extends State<TaskForm>{late final title=TextEditingController(text:widget.initial?.title??'');late final note=TextEditingController(text:widget.initial?.note??'');late Jalali date=widget.initial?.jalaliDue??Jalali.fromGregorian(DateTime.now().add(const Duration(hours:1)));late int hour=widget.initial?.due.hour??DateTime.now().hour;late int minute=widget.initial?.due.minute??DateTime.now().minute;late Category category=widget.initial?.category??Category.custom;late Recurrence recurrence=widget.initial?.recurrence??Recurrence.none;
 Future<void> pickDate()async{final chosen=await showDialog<Jalali>(context:context,builder:(c){int y=date.year,m=date.month,d=date.day;return StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('تاریخ جلالی'),content:Column(mainAxisSize:MainAxisSize.min,children:[Row(children:[const Text('سال'),IconButton(onPressed:()=>set(()=>y--),icon:const Icon(Icons.remove)),Text(fa('$y')),IconButton(onPressed:()=>set(()=>y++),icon:const Icon(Icons.add))]),DropdownButton<int>(value:m,items:List.generate(12,(i)=>DropdownMenuItem(value:i+1,child:Text(Jalali.monthNames[i]))),onChanged:(v)=>set(()=>m=v!)),DropdownButton<int>(value:d.clamp(1,Jalali.daysInMonth(y,m)),items:List.generate(Jalali.daysInMonth(y,m),(i)=>DropdownMenuItem(value:i+1,child:Text(fa('${i+1}')))),onChanged:(v)=>set(()=>d=v!))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('لغو')),FilledButton(onPressed:()=>Navigator.pop(c,Jalali(y,m,d)),child:const Text('تأیید'))]));});if(chosen!=null)setState(()=>date=chosen);}
 Future<void> pickTime()async{await showDialog<void>(context:context,builder:(c)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('زمان ۲۴ ساعته'),content:SizedBox(width:320,child:Column(mainAxisSize:MainAxisSize.min,children:[Text('${fa(two(hour))}:${fa(two(minute))}',style:Theme.of(c).textTheme.headlineMedium),const Text('ساعت'),Wrap(spacing:3,runSpacing:3,children:List.generate(24,(i)=>SizedBox(width:42,height:38,child:OutlinedButton(onPressed:()=>set(()=>hour=i),child:Text(fa(two(i)))))),),const Text('دقیقه'),Wrap(spacing:3,runSpacing:3,children:List.generate(60,(i)=>SizedBox(width:40,height:36,child:OutlinedButton(onPressed:()=>set(()=>minute=i),child:Text(fa(two(i)))))))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('تأیید'))])));}
 IconData icon(Category c)=>switch(c){Category.work=>Icons.work,Category.family=>Icons.family_restroom,Category.finance=>Icons.payments,Category.health=>Icons.health_and_safety,Category.custom=>Icons.label};
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.initial==null?'کار تازه':'ویرایش کار')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:title,maxLines:null,decoration:const InputDecoration(labelText:'عنوان',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:note,maxLines:5,decoration:const InputDecoration(labelText:'یادداشت',border:OutlineInputBorder())),ListTile(title:const Text('تاریخ جلالی'),subtitle:Text(date.format()),trailing:const Icon(Icons.calendar_month),onTap:pickDate),ListTile(title:const Text('زمان'),subtitle:Text('${fa(two(hour))}:${fa(two(minute))}'),trailing:const Icon(Icons.schedule),onTap:pickTime),DropdownButtonFormField<Category>(value:category,decoration:const InputDecoration(labelText:'دسته‌بندی'),items:Category.values.map((x)=>DropdownMenuItem(value:x,child:Row(children:[Icon(icon(x)),const SizedBox(width:8),Text({Category.work:'کار',Category.family:'خانواده',Category.finance:'مالی',Category.health:'سلامت',Category.custom:'سفارشی'}[x]!)]))).toList(),onChanged:(v)=>setState(()=>category=v!)),DropdownButtonFormField<Recurrence>(value:recurrence,decoration:const InputDecoration(labelText:'تکرار'),items:Recurrence.values.map((x)=>DropdownMenuItem(value:x,child:Text({Recurrence.none:'بدون تکرار',Recurrence.daily:'روزانه',Recurrence.weekly:'هفتگی',Recurrence.monthly:'ماهانه',Recurrence.yearly:'سالانه'}[x]!))).toList(),onChanged:(v)=>setState(()=>recurrence=v!),const SizedBox(height:20),FilledButton.icon(onPressed:(){if(title.text.trim().isEmpty)return;final g=date.toGregorian();final due=DateTime(g.year,g.month,g.day,hour,minute);Navigator.pop(context,Task(id:widget.initial?.id??DateTime.now().microsecondsSinceEpoch.toString(),title:title.text.trim(),note:note.text, due:due,category:category,recurrence:recurrence));},icon:const Icon(Icons.save),label:const Text('ذخیره'))]));
}
